import React, { useState, useEffect } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg';

const QuanLyPhuongTien = () => {
    const [viewRoom, setViewRoom] = useState(null);
    const [loading, setLoading] = useState(false);

    // 1. ĐẦU CHỜ BACKEND: Lưu danh sách phương tiện theo phòng
    // Cấu trúc: { "101": [{type: 'Xe máy', plate: '43-A1...'}, ...], "102": [] }
    const [vehiclesData, setVehiclesData] = useState({});

    // Tự động tạo danh sách 45 phòng (9 tầng x 5 phòng) giống hệt code Quản lý hóa đơn
    const allRooms = [];
    for (let floor = 1; floor <= 9; floor++) {
        for (let num = 1; num <= 5; num++) {
            allRooms.push(`${floor}0${num}`);
        }
    }

    // --- LOGIC KẾT NỐI BACKEND (MÔ PHỎNG) ---
    useEffect(() => {
        const fetchAllVehicles = async () => {
            setLoading(true);
            // Sau này: const res = await axios.get('/api/vehicles');

            setTimeout(() => {
                // Giả lập dữ liệu cho vài phòng
                const mockData = {
                    "101": [
                        { id: 1, type: "Xe máy", plate: "43A-123.45" },
                        { id: 2, type: "Ô tô", plate: "43B-999.99" }
                    ],
                    "102": [
                        { id: 3, type: "Xe máy", plate: "43C-456.78" }
                    ],
                    "501": [
                        { id: 4, type: "Ô tô", plate: "43D-000.01" }
                    ]
                };
                setVehiclesData(mockData);
                setLoading(false);
            }, 500);
        };
        fetchAllVehicles();
    }, []);

    return (
        <div style={{
            flex: 1, borderRadius: '30px', display: 'flex', flexDirection: 'column', 
            backgroundImage: `url(${chatBgImg})`, backgroundSize: 'cover',
            backgroundPosition: 'center', overflow: 'hidden', height: 'calc(100vh - 120px)'
        }} className="glass-card">

            {/* Header */}
            <div style={{ padding: '20px', background: 'rgba(0,0,0,0.2)' }}>
                <h2 style={{ color: '#fff', margin: 0, fontSize: '22px' }}>🚗 QUẢN LÝ PHƯƠNG TIỆN</h2>
            </div>

            <div style={{ flex: 1, padding: '20px', display: 'flex', gap: '25px', overflow: 'hidden' }}>

                {/* CỘT TRÁI: DANH SÁCH 45 PHÒNG (Đã bỏ màu vàng/xanh) */}
                <div className="custom-scrollbar" style={{ 
                    width: '220px', display: 'grid', gridTemplateColumns: 'repeat(5, 1fr)', 
                    gap: '8px', alignContent: 'flex-start', overflowY: 'auto',
                    padding: '15px', backgroundColor: 'rgba(0,0,0,0.3)', borderRadius: '20px'
                }}>
                    {allRooms.map(room => (
                        <div key={room} onClick={() => setViewRoom(room)}
                            style={{ 
                                // Chỉ dùng màu Nâu khi được chọn, còn lại để trắng mờ
                                background: viewRoom === room ? '#8b5e5e' : 'rgba(255,255,255,0.8)', 
                                color: viewRoom === room ? '#fff' : '#333',
                                padding: '12px 0', borderRadius: '10px', textAlign: 'center', 
                                fontSize: '12px', fontWeight: 'bold', cursor: 'pointer', transition: '0.2s',
                                boxShadow: viewRoom === room ? '0 4px 10px rgba(0,0,0,0.2)' : 'none',
                                border: 'none'
                            }}>
                            {room}
                        </div>
                    ))}
                </div>

                {/* CỘT PHẢI: CHI TIẾT PHƯƠNG TIỆN */}
                <div style={{ 
                    flex: 1, backgroundColor: '#fff', borderRadius: '30px', 
                    padding: '40px', display: 'flex', flexDirection: 'column', color: '#333'
                }}>
                    {loading ? (
                        <div style={{ flex: 1, display: 'flex', justifyContent: 'center', alignItems: 'center', color: '#8b5e5e', fontWeight: 'bold' }}>
                            ĐANG TẢI DỮ LIỆU...
                        </div>
                    ) : viewRoom ? (
                        <div style={{ animation: 'fadeIn 0.3s', height: '100%', display: 'flex', flexDirection: 'column' }}>
                            {/* Tiêu đề số phòng lớn */}
                            <div style={{ borderBottom: '3px solid #8b5e5e', paddingBottom: '20px', marginBottom: '30px' }}>
                                <span style={{ fontSize: '18px', color: '#8b5e5e', fontWeight: 'bold' }}>THÔNG TIN PHƯƠNG TIỆN</span>
                                <h1 style={{ fontSize: '50px', margin: 0, fontWeight: '900' }}>PHÒNG {viewRoom}</h1>
                            </div>

                            {/* Danh sách xe */}
                            <div className="custom-scrollbar" style={{ flex: 1, overflowY: 'auto', display: 'flex', flexDirection: 'column', gap: '15px' }}>
                                {vehiclesData[viewRoom] && vehiclesData[viewRoom].length > 0 ? (
                                    vehiclesData[viewRoom].map((vehicle, index) => (
                                        <div key={index} style={{ padding: '20px', backgroundColor: '#f9f9f9', borderRadius: '20px', border: '1px solid #eee' }}>
                                            <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
                                                <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                                                    <span style={{ color: '#777', fontSize: '16px' }}>Loại xe:</span>
                                                    <span style={{ fontWeight: 'bold', fontSize: '18px' }}>{vehicle.type}</span>
                                                </div>
                                                <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                                                    <span style={{ color: '#777', fontSize: '16px' }}>Biển số:</span>
                                                    <span style={{ fontWeight: 'bold', fontSize: '18px', color: '#8b5e5e' }}>{vehicle.plate}</span>
                                                </div>
                                            </div>
                                        </div>
                                    ))
                                ) : (
                                    <div style={{ textAlign: 'center', marginTop: '50px' }}>
                                        <div style={{ fontSize: '60px', marginBottom: '10px' }}>🔘</div>
                                        <p style={{ color: '#999', fontSize: '18px' }}>Phòng này hiện chưa đăng ký phương tiện nào.</p>
                                    </div>
                                )}
                            </div>
                        </div>
                    ) : (
                        <div style={{ flex: 1, display: 'flex', justifyContent: 'center', alignItems: 'center', color: '#ccc', fontSize: '20px', fontStyle: 'italic' }}>
                            Vui lòng chọn một số phòng ở bên trái để xem xe...
                        </div>
                    )}
                </div>
            </div>

            <style>{`
                .custom-scrollbar::-webkit-scrollbar { width: 6px; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(0,0,0,0.1); border-radius: 10px; }
                @keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
            `}</style>
        </div>
    );
};

export default QuanLyPhuongTien;
